function is_palindrome(q: seq<int>) : bool
    requires |q| >= 0
{
    var n := |q|;
    var i := 0;
    while i < n / 2
        invariant 0 <= i <= n / 2
        invariant forall j: int :: 0 <= j < i ==> q[j] == q[n - 1 - j]
    {
        if q[i] != q[n - 1 - i] {
            return false;
        }
        i := i + 1;
    }
    return true;
}

function sum(q: seq<int>) : int
    requires |q| >= 0
{
    var total := 0;
    var i := 0;
    while i < |q|
        invariant 0 <= i <= |q|
        invariant total == sum(q[0..i]) // sum of the first i elements
    {
        total := total + q[i];
        i := i + 1;
    }
    return total;
}

